oxy_webhelp_navlinks = {"chatgpt_enterprise_deployed_agent_cloud-d39307e62517":{"topics":[{"title":"ChatGPT Enterprise coverage and requirements for <span class=\"ph\">Agent Cloud<\/span>","shortdesc":"<p class=\"shortdesc\">Deploying ChatGPT Enterprise on <span class=\"ph\">Agent Cloud<\/span> requires a ChatGPT Enterprise         workspace with Compliance API access, as well as administrative roles in both OpenAI and <span class=\"ph\">Agent Cloud<\/span>. Administrators must also review the coverage and limitations of         integration before deploying ChatGPT Enterprise on <span class=\"ph\">Agent Cloud<\/span>.<\/p>","href":"agent_cloud\/chatgpt_ent_prereqs_coverage_agent_cloud.html","attributes":{"data-id":"chatgpt_ent_prereqs_coverage_agent_cloud"},"menu":{"hasChildren":false},"tocID":"chatgpt_ent_prereqs_coverage_agent_cloud-d39307e62532","topics":[]},{"title":"Deploying ChatGPT Enterprise in <span class=\"ph\">Agent Cloud<\/span>","shortdesc":"<p class=\"shortdesc\">Deploy ChatGPT Enterprise in <span class=\"ph\">Agent Cloud<\/span> to enable agent discovery,         conversation ingestion, and tool-call monitoring for a ChatGPT Enterprise         workspace.<\/p>","href":"agent_cloud\/deploying_chatgpt_enterprise_agent_cloud.html","attributes":{"data-id":"deploying_chatgpt_enterprise_agent_cloud"},"menu":{"hasChildren":false},"tocID":"deploying_chatgpt_enterprise_agent_cloud-d39307e62554","topics":[]}]}};